from h34 import *
M=mcq;F=tf;S=short;N=num
b='<rect x="0" y="0" width="720" height="260" fill="#e8f4fb"/><polygon points="0,230 150,90 230,160 360,40 520,170 600,110 720,230" fill="#8c7b6b"/><polygon points="360,40 330,75 360,68 385,78" fill="#fff"/><rect x="0" y="230" width="720" height="40" fill="#8fc77a"/><path d="M520 175 Q 540 215 500 235 Q 470 255 520 262" fill="none" stroke="#2e86ab" stroke-width="8"/><text x="360" y="30" text-anchor="middle" font-weight="bold">Summit (peak)</text><text x="150" y="80" text-anchor="middle">Mountain range</text><text x="450" y="130">Slope</text><text x="40" y="255">Foot of the mountain</text><text x="540" y="250">River</text><text x="560" y="100">Valley between ranges</text>'
svgfile('c4en-mountain-landforms.svg',720,270,b)
chapter(4,'english','a-journey-to-the-magical-mountains','A Journey to the Magical Mountains',
 ('Minam and her grandfather in the Himalayas','Minam, a young girl at the foot of the Himalayas, goes on a special walk with her grandfather, who was once a Sherpa. They picnic by a river, meet yaks, build a snowman, see Mount Everest and promise to protect the mountains. In this chapter you will read the story, learn mountain words, use body-part names for objects, and join sentences with and, or, but and because.'),
 [('The invitation',['Minam lived in a small village at the foot of the mighty Himalayas. She loved listening to her grandfather\'s stories about the mountains, because he was once a Sherpa.','One sunny morning her grandfather said that she had become strong enough to walk a long distance, so he would take her on a special journey to see the Himalayas up close.','Minam was excited and packed rotis with pickle, two water bottles and her favourite fruit, apples.']),
  ('The walk begins',['They set out early in the morning. On the way Minam saw beautiful flowers and tall trees and heard bird sounds she had never heard before.','The air was fresh and cool, and Minam felt very happy.','At a small river with clear water, her grandfather said this is where they would have lunch.','They enjoyed their rotis by the river, watched the fish swim, and Minam dipped her feet in the cool water and laughed while eating an apple.']),
  ('Yaks and snow',['After lunch they climbed higher, and soon they saw yaks. Her grandfather said yaks are very important to mountain people, as they give milk and wool and carry heavy loads.','Higher up the ground was covered with snow, which Minam had never seen so much of before.','She and her grandfather made a small snowman, laughed and played, and made memories that she would value forever.']),
  ('The top of the hill',['Finally they reached the top of a hill and Minam saw the huge peaks of the Himalayas shining in the sun.','Her grandfather pointed to the highest mountain and said that it was Mount Everest, the tallest mountain in the world, which many brave people have tried to climb.','Minam felt happy to be living near such wonderful mountains.']),
  ('The journey home',['As the sun set they started back. On the way they heard beautiful music played by an old man under a tree.','They saw a family of mountain goats jumping from rock to rock, and her grandfather explained that goats are good at climbing and can reach places that are hard for people.','They reached the village when it was dark. Minam was tired but very happy and thanked her grandfather, saying she would never forget the day.','He replied that the mountains are truly magical, because they teach us strength, beauty and the wonders of nature, and that we must respect and protect them.','Minam promised to take care of the mountains and share their magic with everyone she met.']),
  ('Mountain words',['The Himalayas are the tallest mountain range in the world. A Sherpa is a guide who helps climbers in the mountains.','A summit is the top of a mountain, a slope is the side that goes up or down, and the foot is the bottom of the mountain.','A valley is a low area of land between mountains and a plateau is a high flat land. A plain is a wide flat area, and a mountain range is a long row of mountains.','A journey is a trip from one place to another. Memories are things we remember and cherish. Yaks are large strong animals used for milk, wool and carrying loads.']),
  ('Body-part words for objects',['We use names of body parts for things: legs of a table, hands of a clock, foot of a mountain and neck of a bottle.','Mouth of a river, arm of a chair, heart of a city, ear of corn and eye of a needle are more examples.','This is called figurative use, because the object is compared to a body part.']),
  ('Conjunctions',['Words that join words, phrases or sentences are called conjunctions.','And adds information: I have a dog and a cat. Or gives a choice: Do you want an apple or a banana?','But shows a difference: I was tired, but I finished my homework. Because gives a reason: I stayed inside because it was raining.','She was hungry, so she ate a sandwich could also be written as She ate a sandwich because she was hungry.','Choose the conjunction by asking whether you are adding, choosing, contrasting or giving a reason.'])],
 [('Join with the right conjunction: He ran fast. He missed the bus.',[('The second fact is surprising after the first.','It shows a difference.'),('Use but.','But shows contrast.'),('So: He ran fast but he missed the bus.','And would not show the difference.')]),
  ('What is the foot of a mountain?',[('Think about the body part foot.','It is at the bottom.'),('The foot of a mountain is the bottom, where the mountain meets the land.','It is not a real foot.'),('So the foot of the mountain is its lowest part.','The summit is the top.')])],
 ('Tell the story of Minam\'s journey and what she promised her grandfather.',['A long walk with her grandfather','River picnic, yaks, snow and Mount Everest','Mountains teach strength and beauty','She promised to protect them'],['Minam climbed Mount Everest','Minam went alone']),
 ['Minam and her grandfather went on a journey to the Himalayas.','They saw yaks, snow, Mount Everest and mountain goats.','Mountains teach us strength and beauty and must be protected.','The foot of a mountain is its bottom; the summit is its top.','And, or, but and because join sentences in different ways.'],
 [M('1',1,'Who was Minam\'s grandfather once?','A Sherpa',[('A teacher','He was a Sherpa'),('A farmer','He was a Sherpa')],'He guided climbers in the mountains.'),
  M('2',1,'What did Minam pack?','Rotis with pickle, water bottles and apples',[('Rice and fish','Rotis and apples'),('Only sweets','Rotis and apples')],'She packed lunch for the journey.'),
  M('3',1,'Where did they have lunch?','By a small river',[('On the snow','By a river'),('At the village','By a river')],'They watched fish and Minam dipped her feet.'),
  M('4',1,'What did Minam do when she saw snow?','Made a snowman with her grandfather',[('Ran home','She played'),('Cried','She laughed')],'She had never seen so much snow.'),
  M('5',1,'Which is the tallest mountain in the world?','Mount Everest',[('Himalayas','That is a range'),('Hill','Not the tallest')],'Her grandfather pointed to Mount Everest.'),
  M('6',1,'What did Minam promise at the end?','To protect the mountains',[('To climb Everest','She promised protection'),('To leave the village','She promised protection')],'She would take care of the mountains.'),
  M('7',2,'Which animals carry loads in the mountains?','Yaks',[('Goats','Goats climb rocks'),('Fish','Fish live in the river')],'Yaks give milk, wool and carry loads.'),
  M('8',2,'What is a summit?','The top of a mountain',[('The bottom','That is the foot'),('A river','Not the meaning')],'The summit is the highest point.'),
  M('9',2,'Which conjunction gives a reason?','because',[('and','And adds'),('or','Or gives a choice')],'Because gives a reason.'),
  M('10',2,'Which conjunction shows a difference?','but',[('and','And adds'),('because','Gives a reason')],'But shows contrast.'),
  F('11',2,'The ear of corn is a use of a body-part name for an object.',True,'Ear is compared to the part of the corn.'),
  S('12',3,'What do we call a guide who helps climbers in the Himalayas?',['sherpa','a sherpa'],'A Sherpa is a mountain guide.')],
 svgs=[('c4en-mountain-landforms','A mountain with its summit, slope, foot, valley and a river labelled.','The parts of a mountain: summit, slope, foot, valley and river.')],
 keep=['Himalayas','Sherpa'])
